class TrackBuilder {
    public readonly anims: Animation[];
    public add(...anims: Animation[]): this;
    public wait(ms: number): this;
    public build(options?: AnimOptions): TrackAnimation;
}

class TrackAnimation extends Concurrent {
    constructor(animations: Animation[], options?: AnimOptions);
    public override applyOptions(options: AnimOptions): this;
}

