};

import {
    Scene, Entity, Color, Text, Circle, Rect, Line,
    Create, Write, FadeIn, TrackBuilder, Rate
} from "retiam";

export class TelemetryCard extends Entity {
    public frame: Rect;
    public beacon: Circle;
    public titleText: Text;
    public metricValueText: Text;
    public sparkline: Line;
    public footerText: Text;

    constructor() {
        super();
        this.frame = new Rect(5.8, 3.8, { cornerRadius: 0.25 });
        this.frame.paint.fill = new Color(0.06, 0.08, 0.14, 0.88);
        this.frame.paint.setStroke(0.04, new Color(0.18, 0.85, 1.0, 1.0));

        this.beacon = new Circle(0.12);
        this.beacon.paint.fill = new Color(0.1, 0.95, 0.6, 1.0);
        this.beacon.transform.setPositionXYZ(-2.3, 1.3, 0);

        this.titleText = new Text("CORE TELEMETRY", { fontSize: 0.32 });
        this.titleText.transform.setPositionXYZ(-0.7, 1.3, 0);

        this.metricValueText = new Text("99.98%", { fontSize: 0.72 });
        this.metricValueText.transform.setPositionXYZ(-1.2, 0.35, 0);

        this.sparkline = new Line([[-2.4, -0.4], [0, 0.2], [2.4, 0.7]], {
            stroke: new Color(0.1, 0.95, 0.6, 1.0),
            stroke_width: 0.05
        });

        this.footerText = new Text("STATUS: OPTIMAL", { fontSize: 0.18 });
        this.footerText.transform.setPositionXYZ(0, -1.45, 0);

        this.add(this.frame, this.beacon, this.titleText, this.metricValueText, this.sparkline, this.footerText);
    }

    /**
     * Declares the multi-stage creation choreography.
     */
    public override createAnim(t: TrackBuilder): void {
        // Stage 1: Draw outer container
        t.add(new Create(this.frame, { duration: 600 }));

        // Stage 2: Parallel intro of header elements
        t.add(
            new Create(this.beacon, { duration: 350 }),
            new Write(this.titleText, { duration: 450 })
        );

        // Stage 3: Temporal pause
        t.wait(150);

        // Stage 4: Reveal primary metrics and sparkline together
        t.add(
            new Write(this.metricValueText, { duration: 650 }),
            new Create(this.sparkline, { duration: 750 })
        );

        // Stage 5: Pause
        t.wait(100);

        // Stage 6: Footer reveal
        t.add(new FadeIn(this.footerText, { duration: 400 }));
    }
}

// Scene playback
export class MyScene extends Scene {
    public async run() {
        const card1 = new TelemetryCard();
        card1.transform.setPositionXYZ(-3.3, 0, 0);

        // 1. Play with natural duration calculated by TrackBuilder (~2050ms)
        await this.play(new Create(card1));

        const card2 = new TelemetryCard();
        card2.transform.setPositionXYZ(3.3, 0, 0);

        // 2. Play with scaled duration and custom cubic easing
        await this.play(new Create(card2, {
            duration: 3000,
            rate_func: Rate.easeInOutCubic()
        }));
    }
}
